function box(w,h,d,m,x,y,z,parent=scene){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}function sphere(r,m,x,y,z,parent){const o=new THREE.Mesh(new THREE.SphereGeometry(r,16,12),m);o.position.set(x,y,z);o.castShadow=true;parent.add(o);return o}
box(20,.3,18,mats.floor,0,-.15,0);box(20,5,.35,mats.wall,0,2.5,-9);box(.35,5,18,mats.wall,-10,2.5,0);box(.35,5,18,mats.wall,10,2.5,0);box(7,2.6,.12,mats.green,0,2.9,-8.78);box(7.4,.12,.25,mats.wood,0,1.55,-8.7);
for(let x of [-6.8,6.8]){box(2.1,2.6,.12,mat('#8fc7ef'),x,3,-8.76);box(.1,2.6,.14,mats.wall,x,3,-8.66);box(2.1,.1,.14,mats.wall,x,3,-8.66)}
// Low desks frame the play area without blocking the player.
