function frame(now){const dt=Math.min((now-last)/1000||0,.04);last=now;update(dt);const target=new THREE.Vector3(player.position.x,0,player.position.z-1);camera.position.lerp(new THREE.Vector3(player.position.x,14,player.position.z+14),.06);camera.lookAt(target);renderer.render(scene,camera);requestAnimationFrame(frame)}
